diff --git a/repro/unwrapAssertion.ts b/repro/unwrapAssertion.ts
new file mode 100644
index 000000000..05b9339ff
--- /dev/null
+++ b/repro/unwrapAssertion.ts
@@ -0,0 +1,35 @@
+// Repro for TS 5.7 regression: inline type assertion reused for display inside mapped-type template.
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>>
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> }
+    : T['_type']
+
+// Inline assertion (buggy display)
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+type Test = Unwrap<typeof value>
+const t1: number = null! as Test; // expected message to mention { prop1: "hello"; }
+
+// Assertion on a separate line (correct display)
+const strWrapper = stringWrapper() as Wrapper<"hello">;
+const value2 = objWrapper({
+    prop1: strWrapper
+})
+type Test2 = Unwrap<typeof value2>
+const t2: number = null! as Test2; // shows { prop1: "hello"; }
+
+// Indexing shows the actual type is correct ("display-only")
+type Test3 = Unwrap<typeof value>["prop1"]
+const t3: Test3 = "x"; // error mentions '"hello"' -> real type is correct
